806			name     string
807			target   string
808			routeID  string
809			upstream string
810		}{
811			{
812				name:     "junction collapse leaves encoded content byte for byte",
813				target:   "/api//%2F/x//y/?a=1&a=&flag",
814				routeID:  "enc",
815				upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/%2F/x//y/?a=1&a=&flag",
816			},
817			{
