822			},
823			{
824				name:     "empty question mark stays distinct from no query",
825				target:   "/api?",
826				routeID:  "enc",
827				upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/?",
828			},
829			{
830				name:     "root prefix receiving the root path keeps the encoded base",
